import {bagGuests} from './bag-story.js';
import {button,icon,esc} from './ui.js';
export function renderBagStory(progress,sound){
 const round=progress.storyRound||0,g=bagGuests[round];
 const speaker=button(icon('sound'),'kana-audio','icon-button',`aria-label="${g.name} 이름 다시 듣기"`);
 const cards=`<div class="name-match-choices" role="group" aria-label="${g.name}와 짝이 되는 글자 카드">${g.choices.map(text=>button(`<strong lang="ja">${text}</strong>${progress.answered&&text===g.text?icon('check'):''}`,'kana-solve',`secondary name-match-card${progress.answered&&text===g.text?' correct':''}`,`data-id="${text===g.text?'match':text}" aria-label="${text} 글자 카드" ${progress.answered?'disabled':''}`)).join('')}</div>`;
 const count=`<p class="bag-return-count">이름으로 글자 연습</p>`;
 if(progress.phase==='intro')return `${count}<h1>${round===0?'이름표로 글자를 익혀요':round===1?'이번에는 아키':'마지막은 아이'}</h1><div class="bag-reading-help"><strong lang="ja">${g.text}</strong><p>${g.name}</p></div><p class="kana-story">${round===0?'이름표에 쓰인 글자를 쓰고 읽는 연습이에요.<br>마지막에는 카드의 짝을 맞춰 확인해요.':round===1?'새 글자 き를 쓰고, 아키의 이름을 읽어 봐요.':'배운 あ와 い를 다시 쓰고 읽어 봐요.'}</p>${button('쓰기 연습 시작','kana-next')}`;
 if(['reading','quiz'].includes(progress.phase))return `${count}<h1>읽기 연습</h1><p class="kana-story">글자를 하나씩 읽고, 이름으로 이어 읽어 봐요.</p><div class="bag-reading-help"><strong lang="ja">${[...g.text].join(' → ')}</strong><p>${g.name}</p></div><div class="bag-guest-sound"><strong lang="ja">${g.text}</strong>${speaker}</div>${button('카드 짝 맞추기','kana-next')}`;
 if(progress.phase==='solve')return `${count}<h1>같은 이름끼리 이어요</h1><p class="kana-story">${g.name}라고 읽는 글자 카드를 골라 주세요.</p><div class="name-match-source${progress.answered?' matched':''}"><span>${g.name}</span>${speaker}</div><div class="name-match-link${progress.answered?' matched':''}" aria-hidden="true">${progress.answered?icon('check'):icon('arrow')}</div>${cards}${progress.answered?`<p class="kana-story" role="status"><span lang="ja">${g.text}</span>, ${g.name}라고 읽어요.</p>${button(round===2?'다음':'다음 이름 연습','kana-next')}`:`<p class="kana-feedback" role="status">${esc(progress.feedback)}</p>${button('읽기 다시 연습','kana-help','secondary')}`}`;
 if(progress.phase==='summary')return `<span class="kana-case-check" aria-hidden="true">${icon('check')}</span><h1>글자 연습을 마쳤어요</h1><p class="kana-story">あ · お · い · き를 쓰고,<br>세 이름을 읽어 봤어요.</p><div class="bag-finished-names">${bagGuests.map(x=>`<div><strong lang="ja">${x.text}</strong><span>${x.name}</span></div>`).join('')}</div><div class="case-complete-actions">${button('다시 연습하기','kana-restart','secondary')}${button('다음 학습으로','kana-continue','primary','data-id="1"')}</div>`;
 return '';
}
